def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [
        fmt([1]), fmt([2]), fmt([1, 1, 1]), fmt([6, 12, 5, 10]), fmt([3, 12, 5, 10]),
        fmt([10**9] * 5), fmt([1, 2]), fmt([2 ** 29 + 1, 2 ** 29, 2 ** 29 - 1]),
        fmt([2 ** 29, 2 ** 29, 2 ** 29, 2 ** 29]),
    ]
    for n in (2, 3, 4, 6, 9, 14, 20, 30):
        for _ in range(2):
            hi = rng.choice([5, 20, 1000, 10**9])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.choice([2 ** rng.randint(0, 29), 2 ** rng.randint(0, 29) - 1 or 1, 10**9]) for _ in range(100000)]))
    tests.append(fmt([(2 ** 29 if i % 2 == 0 else 2 ** 29 - 1) for i in range(100000)]))
    tests.append(fmt([2 ** 29] * 100000))
    return tests

